class LineWorld:
    def __init__(self, length=5):
        if length < 2:
            raise ValueError('length must be at least 2')
        self.length = length
        self.reset()

    def reset(self):
        self.position = 0
        return self.position

    def step(self, action):
        if action not in (0, 1):
            raise ValueError('action must be 0 (left) or 1 (right)')
        if self.position == self.length - 1:
            raise RuntimeError('Episode has terminated; call reset()')
        self.position = max(0, min(self.length - 1, self.position + (1 if action == 1 else -1)))
        terminated = self.position == self.length - 1
        reward = 1.0 if terminated else -0.01
        return self.position, reward, terminated

env = LineWorld(length=5)
state = env.reset()
print('Initial state:', state)

for action in [1, 1, 1, 1]:
    next_state, reward, terminated = env.step(action)
    print(state, action, reward, next_state, terminated)
    state = next_state
    if terminated:
        break
